      en: ["The forest covers approximately 55% of Canada's total land area.", "It spans an area of roughly 2.7 million square kilometers.", "Boreal peatlands store approximately 300 billion tonnes of carbon.", "Over 3 billion migratory birds breed in this forest every year.", "The forest is home to the world's largest population of woodland caribou.", "Forestry operations generate billions for Canada's GDP annually."],
