      es: ["Altura: 4.019 metros.", "Cumbre más alta de las montañas de la Costa.", "Primera ascensión: 1936.", "Ubicación: Columbia Británica, Canadá.", "Glaciares: incluye el glaciar Waddington.", "Aislamiento topográfico: unos 120 km."],
      pt: ["Altura: 4.019 metros.", "Pico mais alto das Montanhas da Costa.", "Primeira ascensão: 1936.", "Localização: Colúmbia Britânica, Canadá.", "Geleiras: inclui a Geleira Waddington.", "Isolamento topográfico: cerca de 120 km."],
      fr: ["Altitude : 4 019 mètres.", "Plus haut sommet de la chaîne Côtière.", "Première ascension : 1936.", "Lieu : Colombie-Britannique, Canada.", "Glaciers : comprend le glacier Waddington.", "Isolement topographique : environ 120 km."],
