      es: ["Rica cultura escocesa y acadiana", "El lago Bras d'Or es un mar interior", "Espectacular paisaje costero"],
      pt: ["Rica cultura escocesa e acadiana", "O Lago Bras d'Or é um mar interior", "Espetacular paisagem costeira"],
