      es: ["Superficie: 10.311 km².", "Población: aprox. 135.000.", "Punto más alto: White Hill (532 m).", "Parque Nacional: Cape Breton Highlands (950 km²).", "Longitud del Cabot Trail: 298 km.", "Minería del carbón: desde el siglo XVIII."],
      pt: ["Área: 10.311 km².", "População: cerca de 135.000.", "Ponto mais alto: White Hill (532 m).", "Parque Nacional: Cape Breton Highlands (950 km²).", "Comprimento do Cabot Trail: 298 km.", "Mineração de carvão: desde o século XVIII."],
