    descriptionAdvanced: {
      de: "Manitoulin Island liegt im Lake Huron in der Provinz Ontario und ist mit einer Fläche von 2.766 Quadratkilometern die größte Süßwasserinsel der Welt. Geografisch ist die Insel durch ihre Lage auf der Niagara-Schichtstufe geprägt, was zu spektakulären Kalksteinklippen und dem berühmten Cup and Saucer Trail führt. Eine Besonderheit der Insel sind ihre über 100 Binnenseen, von denen einige selbst wieder kleine Inseln beherbergen. Historisch ist Manitoulin seit Jahrtausenden die Heimat der Anishinaabe-Völker, und heute befinden sich sechs First Nations Gemeinschaften auf der Insel. Die erste dauerhafte europäische Siedlung entstand im 19. Jahrhundert, doch die Insel hat ihren ländlichen und ursprünglichen Charakter weitgehend bewahrt. In der Moderne ist Manitoulin über die historische Drehbrücke von Little Current oder per Fähre erreichbar. Die Insel dient als wichtiges kulturelles Zentrum für indigene Kunst und Traditionen sowie als Rückzugsort für Naturbeobachter, die die artenreichen Feuchtgebiete und Alvare der Insel schätzen.",
      hu: "A Manitoulin-sziget az Ontario tartományban található Huron-tavon fekszik, és 2766 négyzetkilométeres területével a világ legnagyobb édesvízi szigete. Földrajzilag a szigetet a Niagara-lépcső határozza meg, ami látványos mészkősziklákat és a híres Cup and Saucer túraútvonalat eredményezi. A sziget különlegessége a több mint 100 belső tava, amelyek közül néhányban saját kis szigetek is találhatók. Történelmileg Manitoulin évezredek óta az anishinaabe népek otthona, és ma hat őslakos közösség él a szigeten. Az első tartós európai település a 19. században jött létre, de a sziget nagyrészt megőrizte vidéki és érintetlen jellegét. A modern korban Manitoulin a Little Current történelmi forgóhídján keresztül vagy komppal érhető el. A sziget fontos kulturális központja az őslakos művészeteknek és hagyományoknak, valamint kedvelt célpontja a természetjáróknak, akik a gazdag vizes élőhelyeket keresik fel.",
      ro: "Insula Manitoulin este situată în Lacul Huron, provincia Ontario, și este cea mai mare insulă aflată într-un lac de apă dulce din lume, având o suprafață de 2.766 de kilometri pătrați. Din punct de vedere geografic, insula face parte din Escarpamentul Niagara, ceea ce îi conferă faleze spectaculoase de calcar și trasee montane renumite, precum Cup and Saucer. O caracteristică unică a insulei este prezența a peste 100 de lacuri interioare, unele dintre acestea având la rândul lor propriile insule. Istoric, Manitoulin este de milenii căminul popoarelor Anishinaabe, găzduind în prezent șase comunități ale Primelor Națiuni. Prima așezare europeană permanentă a fost înființată în secolul al XIX-lea, însă insula și-a păstrat în mare măsură caracterul rural. În epoca modernă, accesul se face prin podul turnant istoric de la Little Current sau cu feribotul. Insula reprezintă un centru cultural major pentru arta indigenă și o destinație de top pentru ecoturism datorită ecosistemelor sale rare.",
      en: "Manitoulin Island is situated in Lake Huron, Ontario, and is the largest freshwater island in the world, covering 2,766 square kilometers. Geographically, the island is part of the Niagara Escarpment, resulting in dramatic limestone cliffs and the famous Cup and Saucer trail vistas. A unique feature of the island is its 108 internal lakes, some of which contain their own smaller islands. Historically, Manitoulin has been the home of Anishinaabe peoples for millennia, and today it hosts six vibrant First Nations communities. The first permanent European settlements appeared in the 19th century, yet the island has largely maintained its rural and rugged character. In modern times, Manitoulin is accessible via the historic swing bridge at Little Current or by ferry from the mainland. The island serves as a significant cultural hub for indigenous arts and traditions, as well as a sanctuary for nature enthusiasts drawn to its diverse wetlands and rare alvar habitats.",
      es: "La isla Manitoulin es la isla más grande del mundo situada en un lago interior, ubicada en el lago Hurón, en la provincia canadiense de Ontario. Tiene una superficie de 2.766 km² y unos 13.000 habitantes. La isla es conocida por su cultura Anishinaabe y sus numerosos lagos, incluido el lago Manitou, el lago más grande del mundo en una isla de agua dulce. La economía está marcada por el turismo, la agricultura y la pesca. La isla está conectada con tierra firme por el puente giratorio Little Current.",
      pt: "A ilha Manitoulin é a maior ilha do mundo num lago interior, situada no lago Huron, na província canadiana de Ontário. Tem uma área de 2.766 km² e cerca de 13.000 habitantes. A ilha é conhecida pela sua cultura Anishinaabe e pelos seus numerosos lagos, incluindo o lago Manitou, o maior lago numa ilha de água doce. A economia é dominada pelo turismo, agricultura e pesca. A ilha está ligada ao continente pela Little Current Swing Bridge.",
      fr: "L'île Manitoulin est la plus grande île lacustre au monde, située dans le lac Huron, dans la province canadienne de l'Ontario. Elle couvre une superficie de 2 766 km² et compte environ 13 000 habitants. L'île est réputée pour sa culture Anishinaabe et ses nombreux lacs, dont le lac Manitou, le plus grand lac situé sur une île lacustre. L'économie est axée sur le tourisme, l'agriculture et la pêche. L'île est reliée au continent par le pont tournant de Little Current.",
    },
    factsAdvanced: {
      de: ["Größte Süßwasserinsel der Erde mit 2.766 km² Fläche", "Beherbergt 108 eigene Binnenseen auf der Insel", "Der Lake Manitou ist der weltgrößte See auf einer Insel", "Die Drehbrücke von Little Current wurde 1913 erbaut", "Heimat von sechs verschiedenen First Nations Gemeinschaften", "Höchste Erhebung liegt bei etwa 350 Metern"],
      hu: ["A világ legnagyobb édesvízi szigete (2766 km²)", "Összesen 108 belső tó található a szigeten", "A Manitou-tó a világ legnagyobb szigeten belüli tava", "A Little Current-i forgóhíd 1913-ban épült", "Hat különböző őslakos (First Nations) közösség otthona", "A sziget legmagasabb pontja 350 méter körül van"],
      ro: ["Cea mai mare insulă într-un lac din lume (2.766 km²)", "Insula conține 108 lacuri interioare proprii", "Lacul Manitou este cel mai mare lac pe o insulă din lume", "Podul turnant din Little Current a fost construit în 1913", "Găzduiește șase comunități ale Primelor Națiuni", "Cea mai înaltă cotă de pe insulă este de circa 350 metri"],
      en: ["World's largest freshwater island at 2,766 square km", "The island contains 108 of its own internal lakes", "Lake Manitou is the largest lake-on-an-island in the world", "The Little Current swing bridge was completed in 1913", "Home to six distinct First Nations communities", "The highest elevation on the island is roughly 350 meters"],
      es: ["Superficie: 2.766 km².", "Población: aprox. 13.000.", "Isla más grande en un lago de agua dulce.", "Número de lagos en la isla: más de 100.", "Superficie del lago Manitou: 104 km².", "Puente Little Current: longitud 152 m."],
      pt: ["Área: 2.766 km².", "População: aprox. 13.000.", "Maior ilha num lago de água doce.", "Número de lagos na ilha: mais de 100.", "Área do lago Manitou: 104 km².", "Ponte Little Current: comprimento 152 m."],
      fr: ["Superficie : 2 766 km².", "Population : env. 13 000.", "Plus grande île située sur un lac d'eau douce.", "Nombre de lacs sur l'île : plus de 100.", "Superficie du lac Manitou : 104 km².", "Pont de Little Current : longueur 152 m."],
    },
