      pt: ["Comprimento: 3.185 quilómetros.", "Nascente: Lago Marsh, Yukon.", "Foz: Mar de Bering.", "Bacia hidrográfica: 832.000 km².", "Corrida ao ouro de Klondike: 1896-1899.", "População de salmão: milhões de peixes anualmente."],
      fr: ["Longueur : 3 185 kilomètres.", "Source : Lac Marsh, Yukon.", "Embouchure : Mer de Béring.", "Bassin versant : 832 000 km².", "Ruée vers l'or du Klondike : 1896-1899.", "Population de saumons : des millions chaque année."],
