      es: ["Altura: 5.489 m", "Descubierto en 1741 por Vitus Bering", "Montaña fronteriza entre Alaska y Yukón", "Parte de las montañas San Elías", "Glaciar Malaspina: aprox. 3.900 km²", "Patrimonio de la Humanidad de la UNESCO desde 1979"],
