      fr: ["Altitude : 5 489 m", "Découvert en 1741 par Vitus Bering", "Montagne frontalière entre l'Alaska et le Yukon", "Fait partie de la chaîne Saint-Élie", "Glacier Malaspina : env. 3 900 km²", "Patrimoine mondial de l'UNESCO depuis 1979"],
